<!DOCTYPE html>
<html>
<head>
<title>Conway's Game of Life</title>
<style>
body {
  background-color: #1e1e1e;
  display: flex;
  flex-direction: column;
  align-items: center;
}

#grid {
  margin-top: 20px;
  border: 2px solid #555;
}

.cell {
  width: 16px;
  height: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 14px;
  color: #fff;
  border-radius: 4px;
}

.alive {
  background-color: #28a745;
}

.dead {
  background-color: #37474f;
}

#controls {
  margin-top: 20px;
  display: flex;
  justify-content: center;
}

button {
  padding: 10px 20px;
  font-size: 16px;
  background-color: #37474f;
  color: #fff;
  border: none;
  cursor: pointer;
  margin: 5px;
}

button:hover {
  background-color: #555;
}
</style>
</head>
<body>

<h1>Conway's Game of Life</h1>

<canvas id="life" width="400" height="400"></canvas>

<div id="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
</div>

<script>
const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d');
const w = 400;
const h = 400;
const cellSize = 16;
let grid = [];

function get(x, y) {
  if (x < 0 || x >= w / cellSize || y < 0 || y >= h / cellSize) return 0;
  return grid[Math.floor(y * w / cellSize)][Math.floor(x * h / cellSize)];
}

function set(x, y, v) {
  if (x < 0 || x >= w / cellSize || y < 0 || y >= h / cellSize) return;
  grid[Math.floor(y * w / cellSize)][Math.floor(x * h / cellSize)] = v;
}

function step() {
  const nextGrid = [];
  for (let y = 0; y < h / cellSize; y++) {
    nextGrid[y] = [];
    for (let x = 0; x < w / cellSize; x++) {
      let liveNeighbors = 0;
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          if (i === 0 && j === 0) continue;
          liveNeighbors += get(x + j, y + i);
        }
      }

      nextGrid[y][x] = (get(x, y) === 1) ? (liveNeighbors == 2 || liveNeighbors == 3) : (liveNeighbors == 3);
    }
  }

  for (let y = 0; y < h / cellSize; y++) {
    for (let x = 0; x < w / cellSize; x++) {
      set(x, y, nextGrid[y][x]);
    }
  }
  draw();
}

function clear() {
  for (let y = 0; y < h / cellSize; y++) {
    for (let x = 0; x < w / cellSize; x++) {
      set(x, y, 0);
    }
  }
  draw();
}

function draw() {
  ctx.clearRect(0, 0, w, h);
  for (let y = 0; y < h / cellSize; y++) {
    for (let x = 0; x < w / cellSize; x++) {
      const cell = grid[y][x];
      if (cell === 1) {
        ctx.fillStyle = '#28a745';
      } else {
        ctx.fillStyle = '#37474f';
      }
      ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
    }
  }
}

function randomSeed() {
  for (let y = 0; y < h / cellSize; y++) {
    for (let x = 0; x < w / cellSize; x++) {
      set(x, y, Math.random() < 0.5 ? 1 : 0);
    }
  }
  draw();
}

const stepButton = document.getElementById('step');
const playButton = document.getElementById('play');
const randomButton = document.getElementById('random');
const clearButton = document.getElementById('clear');

let autoRun = false;

playButton.addEventListener('click', () => {
  autoRun = !autoRun;
  playButton.textContent = autoRun ? 'Pause' : 'Play';
});


stepButton.addEventListener('click', step);
randomButton.addEventListener('click', randomSeed);
clearButton.addEventListener('click', clear);

// Initial grid setup (can be anything)
for(let i=0; i<50; ++i){
    for(let j=0; j<50; ++j){
        set(j,i,Math.random() < 0.7 ? 1 : 0);
    }
}

draw();


window.life = {
  w, h,
  get(x, y),
  set(x, y, v),
  step(),
  clear()
};
</script>

</body>
</html>
